{
  "Document Name": [
    "CO-BRANDING AGREEMENT"
  ],
  "Parties": [
    "Lucent Technologies Inc., a Delaware corporation having a principal place of business at 600 Mountain Avenue, Murray Hill, New Jersey 07974 (\"Lucent\") and mPhase Technologies Inc., a New Jersey corporation located at 587 Connecticut Avenue, Norwalk, Connecticut 068545 (\"mPhase\") (each individually, \"a Party\" and, collectively, \"the Parties\")"
  ],
  "Agreement Date": [
    "this 21st day of January 2003"
  ],
  "Effective Date": [],
  "Expiration Date": [
    "The Term of this Agreement will commence on the date above, and shall continue for a term of one (1) year."
  ],
  "Renewal Term": [
    "mPhase shall have the right to annually renew this agreement for a period of one year upon each annual expiration with the written consent of Lucent, which written consent shall not be unreasonably withheld."
  ],
  "Notice Period To Terminate Renewal": [],
  "Governing Law": [
    "The validity, construction and performance of this Agreement shall be governed by the laws of the State of New York."
  ],
  "Termination For Convenience": [],
  "Anti-Assignment": [
    "Neither Party shall be liable to the other for special, incidental, or consequential damages, even if such Party has been advised of the possibility of such damages."
  ],
  "Change Of Control": [
    "This Agreement shall terminate in the event of a significant change in the management or ownership of mPhase or in the event mPhase is the subject of any bankruptcy proceedings."
  ],
  "Cap On Liability": [
    "Neither Party shall be liable to the other for special, incidental, or consequential damages, even if such Party has been advised of the possibility of such damages."
  ],
  "Uncapped Liability": [],
  "Minimum Commitment": [],
  "Exclusivity": [],
  "Audit Rights": [
    "mPhase agrees to allow Lucent to inspect the Approved Uses bearing the Lucent Co-Branding Logo, to ensure that those uses reviewed and approved pursuant to the procedure set forth in Schedule B continue to be in compliance with the terms of this Agreement."
  ]
}

